            List<EnrichedLogSegment> candidateLogSegments = new ArrayList<>();
            List<LogSegment> segments = log.logSegments(fromOffset, Long.MAX_VALUE);
            if (!segments.isEmpty()) {
                // The resolved copy lag values. A value of -1 in the config resolves to the effective local
                // retention, otherwise the configured value (0 means no delay) is used.
                long copyLagMs = log.config().remoteCopyLagMs();
                long copyLagBytes = log.config().remoteCopyLagBytes();
                long currentTimeMs = time.milliseconds();
                long totalLogSize = log.size();
                // The cumulative size of the segments that have already been considered as candidates.
                long cumulativeSegmentSize = 0;
                for (int idx = 1; idx < segments.size(); idx++) {
                    LogSegment previousSeg = segments.get(idx - 1);
                    LogSegment currentSeg = segments.get(idx);
                    // Segments must be below the last stable offset. Since segments are ordered by increasing
                    // base-offset, no further segment can qualify once this one exceeds the last stable offset.
                    if (currentSeg.baseOffset() > lastStableOffset) {
                        break;
                    }
                    if (isSegmentReadyToCopy(previousSeg, copyLagMs, copyLagBytes, currentTimeMs, totalLogSize, cumulativeSegmentSize)) {
                        candidateLogSegments.add(new EnrichedLogSegment(previousSeg, currentSeg.baseOffset()));
                        cumulativeSegmentSize += previousSeg.size();
                    } else {
                        // The segment is not eligible yet; since segments are ordered, all the following
                        // segments are newer and cannot be eligible either, so we stop here.
                        break;
                    }
                }
                // Discard the last active segment
            }
            return candidateLogSegments;
        }

        /**
         * Determines whether the given segment is eligible to be copied to remote storage based on the configured
         * copy lag. The behaviour is:
         * <ul>
         *     <li>If either resolved copy lag value is 0, the segment is eligible immediately (no delay).</li>
         *     <li>If both resolved copy lag values are less than or equal to 0 (i.e. effectively unlimited), the
         *         segment is not eligible.</li>
         *     <li>When only the time-based lag is configured (&gt; 0), the segment is eligible once its age reaches
         *         the configured lag. When only the size-based lag is configured (&gt; 0), the segment is eligible
         *         once the accumulated local size lag reaches the configured lag. When both are configured, the
         *         segment is eligible if either condition is satisfied.</li>
         * </ul>
         */
        private boolean isSegmentReadyToCopy(LogSegment segment,
                                             long copyLagMs,
                                             long copyLagBytes,
                                             long currentTimeMs,
                                             long totalLogSize,
                                             long cumulativeSegmentSize) {
            if (copyLagMs == 0 || copyLagBytes == 0) {
                return true;
            }
            if (copyLagMs <= 0 && copyLagBytes <= 0) {
                return false;
            }
            boolean eligible = false;
            if (copyLagMs > 0) {
                eligible = isSegmentAgedForCopy(segment, copyLagMs, currentTimeMs);
            }
            if (!eligible && copyLagBytes > 0) {
                eligible = (totalLogSize - cumulativeSegmentSize) >= copyLagBytes;
            }
            return eligible;
        }

